namespace RonSijm.FluidHumidifier.Factories.ConnectCampaignsV2;

public class CampaignFactory(string resourceName = null, Action<Humidifier.ConnectCampaignsV2.Campaign> factoryAction = null) : ResourceFactory<Humidifier.ConnectCampaignsV2.Campaign>(resourceName)
{

    internal InnerCampaignCommunicationLimitsConfigFactory CommunicationLimitsOverrideFactory { get; set; }

    internal InnerCampaignChannelSubtypeConfigFactory ChannelSubtypeConfigFactory { get; set; }

    internal InnerCampaignScheduleFactory ScheduleFactory { get; set; }

    internal InnerCampaignCommunicationTimeConfigFactory CommunicationTimeConfigFactory { get; set; }

    internal InnerCampaignSourceFactory SourceFactory { get; set; }

    protected override Humidifier.ConnectCampaignsV2.Campaign Create()
    {
        var campaignResult = CreateCampaign();
        factoryAction?.Invoke(campaignResult);

        return campaignResult;
    }

    private Humidifier.ConnectCampaignsV2.Campaign CreateCampaign()
    {
        var campaignResult = new Humidifier.ConnectCampaignsV2.Campaign
        {
            GivenName = InputResourceName,
        };

        return campaignResult;
    }
    public override void CreateChildren(Humidifier.ConnectCampaignsV2.Campaign result)
    {
        base.CreateChildren(result);

        result.CommunicationLimitsOverride ??= CommunicationLimitsOverrideFactory?.Build();
        result.ChannelSubtypeConfig ??= ChannelSubtypeConfigFactory?.Build();
        result.Schedule ??= ScheduleFactory?.Build();
        result.CommunicationTimeConfig ??= CommunicationTimeConfigFactory?.Build();
        result.Source ??= SourceFactory?.Build();
    }

} // End Of Class

